import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

RULES_TEXT = (
    'This market will resolve to "Up" if the time-weighted average price (TWAP) of Bitcoin, '
    "generated by Chainlink, of the time range specified in the title is greater than or equal "
    'to the price at the beginning of that range. Otherwise, it will resolve to "Down".\n'
    "The resolution source for this market is information from Chainlink, specifically the "
    "BTC/USD TWAP data stream available at https://data.chain.link/streams/btc-usd-twap-60s-streams.")

EXPECTED_RULES = {"twap_enabled": True, "twap_lookback_seconds": [60],
                  "resolution_mechanism": "oracle", "source_contains": "chain.link",
                  "comparator_phrase": "greater than or equal to"}


def gamma_event(duration="5m", lookback=60, closed=False, outcome_prices=("0.5", "0.5"),
                meta=None, text=RULES_TEXT):
    """Shape copied from a live Gamma /events/slug/btc-updown-5m-* response (Nov 2026)."""
    return {
        "title": "Bitcoin Up or Down - November 9, 8:50AM-8:55AM ET",
        "eventMetadata": meta,
        "markets": [{
            "question": "Bitcoin Up or Down - November 9, 8:50AM-8:55AM ET",
            "conditionId": "0xabc",
            "clobTokenIds": '["111", "222"]',
            "outcomes": '["Up", "Down"]',
            "outcomePrices": '["%s", "%s"]' % outcome_prices,
            "resolutionSource": f"https://data.chain.link/streams/btc-usd-twap-{lookback}s-streams",
            "description": text.replace("twap-60s", f"twap-{lookback}s"),
            "cryptoMarketConfig": {"id": f"btc-{duration}-twap-{lookback}", "asset": "btc",
                                   "duration": duration, "twapEnabled": True,
                                   "twapLookbackSeconds": lookback},
            "resolutionMechanism": "oracle",
            "feesEnabled": True, "feeType": "crypto_fees_v2",
            "feeSchedule": {"exponent": 1, "rate": 0.07, "takerOnly": True, "rebateRate": 0.2},
            "orderPriceMinTickSize": 0.01, "orderMinSize": 5,
            "acceptingOrders": not closed, "closed": closed,
        }],
    }
